export type AssetCategory =
  | 'character'
  | 'enemy'
  | 'portrait'
  | 'tileset'
  | 'map'
  | 'ui'
  | 'icon'
  | 'background'
  | 'audio'
  | 'structure';

export type AssetStatus = 'placeholder' | 'final';

export interface AssetDimensions {
  width: number;
  height: number;
}

export interface AssetDefinition {
  id: string;
  category: AssetCategory;
  intendedUse: string;
  /** Path relative to /assets/ under public/, e.g. "sprites/characters/player.png". */
  filePath: string;
  /** null for asset types dimensions don't apply to (audio, Tiled maps). */
  dimensions: AssetDimensions | null;
  /** One animation frame's size within `dimensions` - present only for sprite sheets. Absent
   *  means the whole image is a single static frame (every asset today except sprite.player).
   *  Columns/rows are derived arithmetically (dimensions ÷ frameSize) rather than stored, since no
   *  consumer needs ragged rows. */
  frameSize?: AssetDimensions;
  status: AssetStatus;
  notes: string;
}

/**
 * Single source of truth for every game asset. Code never imports an image/audio/map
 * file path directly — it looks the asset up here by id via assetManager.getAsset().
 * Swapping a placeholder for final art is a one-line edit to this file.
 */
