    notes:
      "EXPERIMENTAL auto-generation via scripts/estimate_transform_equipment_layer.py, since the shape differs from its family's hand-positioned reference (weathered-walking-staff) - not a simple recolor. Per frame: PCA on the reference frame's own alpha-mask pixel cloud estimates its rotation angle; the same PCA run on spiritwood's own flat icon estimates its native angle; the icon art is rotated by the difference, scaled to match the reference frame's recorded anchor-table height, centered on its recorded (cx,cy), then clipped to the reference frame's own alpha silhouette (reproduces the reference's hand-tuned grip-trim notch for free, at the cost of constraining spiritwood's own width to the reference's). Verified by eye against the base body across all 4 directions x 4 frames, both walking and running - reads convincingly as gripped and follows the arm swing naturally, but this technique is inherently less certain than a direct recolor or real hand-positioning, so treat any future frame that looks off as a candidate for manual touch-up rather than assuming the algorithm is exactly right. UPDATE: exactly that happened - the user hand-fixed several frames on the male sheet directly (the estimate-transform technique's own known uncertainty, not a build-pipeline bug). Female sheet was checked and didn't need the same fix. No other item recolors from this sheet (unlike the walking-staff/cane family's weathered-walking-staff/ironwood-walking-staff pair), so this is a standalone fix with nothing further to cascade.",
